/** Each conversation keeps this many of its newest messages. Past that, the oldest are dropped first. */
export const MAX_MESSAGES_PER_CONVERSATION = 100;

export type DeliveryStatus =
  | "sending"
  | "delivered"
  /** Accepted, but the receiver had no open connection. The backend doesn't store it, so it's gone. */
  | "undelivered"
  | "failed";

export type Message = {
  /** The message's id on the wire: a UUID, generated by the sender's client. */
  key: string;
  mine: boolean;
  text: string | null;
  url: string | null;
  sentAt: string;
  status?: DeliveryStatus;
  error?: string;
  /** On a message I sent: when the other person read it. */
  readAt?: string;
  /** On a message I received: the read receipt has gone out. */
  readReceiptSent?: boolean;
};

export type Conversation = {
  peerId: number;
  messages: Message[];
  unread: number;
  updatedAt: string;
};

export type ChatState = Record<number, Conversation>;

export type ChatAction =
  | { type: "open"; peerId: number }
  | { type: "add"; peerId: number; message: Message; unread?: boolean }
  | { type: "update"; peerId: number; key: string; patch: Partial<Message> }
  | { type: "read"; peerId: number; key: string; readAt: string };

/** A v4 UUID. Not crypto.randomUUID(): that only exists on HTTPS and localhost. */
export function newMessageId() {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function conversation(state: ChatState, peerId: number): Conversation {
  return state[peerId] ?? { peerId, messages: [], unread: 0, updatedAt: new Date().toISOString() };
}

export function chatReducer(state: ChatState, action: ChatAction): ChatState {
  const current = conversation(state, action.peerId);
  switch (action.type) {
    case "open":
      return { ...state, [action.peerId]: { ...current, unread: 0 } };
    case "add":
      // Ids come from the sender, and "Send again" reuses one in case the first copy arrived
      if (current.messages.some((message) => message.key === action.message.key)) return state;
      return {
        ...state,
        [action.peerId]: {
          ...current,
          messages: [...current.messages, action.message].slice(-MAX_MESSAGES_PER_CONVERSATION),
          unread: current.unread + (action.unread ? 1 : 0),
          updatedAt: action.message.sentAt,
        },
      };
    case "update":
      return {
        ...state,
        [action.peerId]: {
          ...current,
          messages: current.messages.map((message) =>
            message.key === action.key ? { ...message, ...action.patch } : message,
          ),
        },
      };
    case "read":
      // The reader chooses the id, so it can only touch what I sent to them, and can't start a conversation
      if (!state[action.peerId]) return state;
      return {
        ...state,
        [action.peerId]: {
          ...current,
          messages: current.messages.map((message) =>
            message.key === action.key && message.mine ? { ...message, readAt: action.readAt } : message,
          ),
        },
      };
  }
}

// The backend keeps no history, so this browser's copy is the only one
const historyKey = (userId: number) => `chat.history.${userId}`;

export function loadHistory(userId: number): ChatState {
  let state: ChatState;
  try {
    state = JSON.parse(localStorage.getItem(historyKey(userId)) ?? "{}");
  } catch {
    return {};
  }
  // A message still "sending" when the page closed will never get its ack
  for (const conversation of Object.values(state)) {
    // History saved before the limit existed can be longer
    conversation.messages = conversation.messages.slice(-MAX_MESSAGES_PER_CONVERSATION);
    for (const message of conversation.messages) {
      // Saved before ids became UUIDs; "Send again" needs one the server accepts
      if (message.key.startsWith("local-")) message.key = newMessageId();
      if (message.status === "sending") {
        message.status = "failed";
        message.error = "Connection lost";
      }
    }
  }
  return state;
}

export function saveHistory(userId: number, state: ChatState) {
  try {
    localStorage.setItem(historyKey(userId), JSON.stringify(state));
  } catch {
    // Storage full or blocked: the chat still works, it just won't survive a reload
  }
}

export function clearHistory(userId: number) {
  localStorage.removeItem(historyKey(userId));
}
